// Configuration for cuenv installation in CI
#CuenvConfig: {
	// Source for cuenv binary in CI
	// - "native": Build using native Rust/Go toolchains (no Nix)
	// - "artifact": Use pre-built artifact from earlier CI job
	// - "git": Build from git checkout (requires Nix)
	// - "nix": Install via Nix flake (uses the configured Nix cache contributor)
	// - "homebrew": Install via Homebrew tap (no Nix required)
	// - "release": Download pre-built binary from GitHub Releases (default)
	source?: "native" | "artifact" | "git" | "nix" | "homebrew" | *"release"

	// Version to install
	// - "self": Use current checkout (default, for git/nix source)
	// - "latest": Latest release (for release mode)
	// - "0.17.0": Specific version tag
	version?: string | *"self"
}

package schema

// Closedness. Consumers embed `schema.#Project` (or `schema.#Base`) at file
// level. Before CUE language v0.18 that leaves the file's own struct open,
// and a field typed with a bare definition reference (`config?: #Config`)
// is left open with it. Referencing the definition inside a struct literal
// (`config?: {#Config}`) keeps it closed under every CUE release and
// language version, so a misspelled nested field is an error. Definitions
// are already closed, so the schema never wraps them in close(): on CUE
// v0.17+ close() around an embedded definition rejects the definition's own
// fields under file-level embedding. The inline passthrough arm of
// #InfrastructureStateToken is the exception: it is not a definition, and an
// open arm would accept extra fields. scripts/check-schema-compat.sh checks
// both properties.
//
// Exception: the `tasks`, `services` and `images` maps reference #Task,
// #TaskGroup, #Service and #ContainerImage directly. `dependsOn` and pipeline
// task lists are typed references to these entries, and cuenv's CUE fork
// shares such a reference only when the entry was constrained by a direct
// definition reference; inside a struct literal the sharing is lost and
// evaluation becomes exponential in the depth of the dependency graph (see
// docs/design/specs/cue-recursive-sharing.md). The cost is that, before
// language v0.18, a misspelled top-level field of an entry written without
// `schema.#Task &` (or `schema.#Service &`, `schema.#ContainerImage &`) is
// ignored. Nested fields are still checked.
#Base: {
	config?: {#Config}
	env?: {#Env}
	formatters?: {#Formatters}
	runtime?: #Runtime
	hooks?: {#Hooks}
	vcs?: [#VcsDependencyName]: {#VcsDependency}
}

#ProjectName: string & =~"^[a-zA-Z0-9._-]+$"

#VcsDependencyName: string & =~"^[a-zA-Z0-9_-][a-zA-Z0-9._-]*$" & !~"\\.\\."

#Project: {
	#Base
	name!: #ProjectName
	ci?: {#CI}
	cache?: {#Cache}
	release?: {#Release}
	// Named tasks and groups derive fully-qualified runtime names from their
	// field labels. Sequences are handled by the Go bridge because list element
	// aliases are not implemented in CUE yet.
	tasks?: [taskName=string]: ((#Task | #TaskGroup) & {
		_cuenvPrefix: ""
		_cuenvSelf:   taskName
	}) | #TaskSequence
	// Services live in their own field but share the project DAG.
	// Services may depend on tasks (build → run); tasks may depend on
	// services (db ready → seed task). Cycles forbidden as with tasks.
	services?: [svcName=string]: #Service & {
		_cuenvPrefix: ""
		_cuenvSelf:   svcName
	}
	// Container image builds — declarative image definitions that
	// participate in the task DAG and produce output references
	// (ref, digest) consumable by tasks and other images.
	images?: [imageName=string]: #ContainerImage & {
		_cuenvPrefix: ""
		_cuenvSelf:   imageName
	}
	codegen?: {#Codegen}
	// Infrastructure managed through Terraform provider plugins.
	infrastructure?: {#Infrastructure}
}

package schema

// Part of an interpolated environment variable.
// Can be a literal string or a secret that needs runtime resolution.
#EnvPart: string | #Secret

// Interpolated environment variable (array of parts).
// Parts are concatenated at runtime after resolving any secrets.
#InterpolatedEnv: [...#EnvPart]

// Environment variable value with optional policies
// Being a definition, it is closed, which keeps it distinct from a direct
// #Secret in #EnvironmentVariable
#EnvironmentVariableWithPolicies: {
	value: string | int | bool | #Secret | #InterpolatedEnv
	policies?: [...#Policy]
}

// Host environment variable passthrough for task environments.
// HOME cannot be passed through explicitly; set hermetic to false to inherit
// the caller's environment, including HOME.
// Forwards a host process env var into the task environment.
// The optional `name` field specifies which host var to read;
// when omitted the Rust executor uses the env map key.
#EnvPassthrough: {
	cuenvPassthrough: true
	name?:            string & !~"(?i)^HOME$"
}

// Environment variable can be a simple value or a value with policies
#EnvironmentVariable: string | int | bool | #Secret | #InterpolatedEnv | #EnvironmentVariableWithPolicies | #EnvPassthrough

// We support non-string types for constraints
// but when exported to the actual environment,
// these will always be strings.
#Environment: {
	[=~"^[A-Z0-9_]*$"]: #EnvironmentVariable
}

// #Env defines the structure for environment variable configuration
#Env: {
	#Environment

	// Environment-specific overrides
	environment?: [string]: #Environment
}

package schema

// =============================================================================
// Base execution types
// =============================================================================
//
// Tasks and service entrypoints share two fundamental shapes: a structured
// command+args invocation, or an inline script. Extracting them as base types
// lets #Service.entrypoint accept the same literal shape users already know
// from tasks, and lets a service reuse an existing task definition by
// reference.

// Command-based execution: a program plus its arguments.
#Command: {
	command: string
	args?: [...(string | #TaskOutputRef)]
}

// Script-based execution: an inline script interpreted by a shell.
#Script: {
	script:        string
	scriptShell?:  #ScriptShell | *"bash"
	shellOptions?: #ShellOptions
}

package schema

// #Formatters configures language-specific code formatters.
// Each formatter can specify file patterns and tool-specific options.
#Formatters: {
	rust?: #RustFormatter
	nix?:  #NixFormatter
	go?:   #GoFormatter
	cue?:  #CueFormatter
}

// #RustFormatter configures rustfmt for Rust files.
#RustFormatter: {
	// Whether this formatter is enabled (default: true)
	enabled: bool | *true

	// Glob patterns for files to format (default: ["*.rs"])
	includes: [...string] | *["*.rs"]

	// Rust edition for formatting rules
	edition?: "2018" | "2021" | "2024"
}

// #NixFormatter configures Nix file formatting.
#NixFormatter: {
	// Whether this formatter is enabled (default: true)
	enabled: bool | *true

	// Glob patterns for files to format (default: ["*.nix"])
	includes: [...string] | *["*.nix"]

	// Which Nix formatter tool to use
	tool: "nixfmt" | "alejandra" | *"nixfmt"
}

// #GoFormatter configures gofmt for Go files.
#GoFormatter: {
	// Whether this formatter is enabled (default: true)
	enabled: bool | *true

	// Glob patterns for files to format (default: ["*.go"])
	includes: [...string] | *["*.go"]
}

// #CueFormatter configures cue fmt for CUE files.
#CueFormatter: {
	// Whether this formatter is enabled (default: true)
	enabled: bool | *true

	// Glob patterns for files to format (default: ["*.cue"])
	includes: [...string] | *["*.cue"]
}

