package schema

// =============================================================================
// Task API v2 - Explicit Types
// =============================================================================
//
// Users annotate tasks with their type to unlock specific semantics:
//   - #Task: Single command or script
//   - #TaskGroup: Parallel execution (all children run concurrently)
//   - #TaskSequence: Sequential execution (steps run in order)
//
// Example:
//   tasks: {
//       build: #Task & { command: "cargo build" }
//       check: #TaskGroup & {
//           type: "group"
//           lint: #Task & { command: "cargo clippy" }
//           test: #Task & { command: "cargo test" }
//       }
//       deploy: #TaskSequence & [
//           #Task & { command: "build" },
//           #Task & { command: "push" },
//       ]
//   }

// Union of all task types - explicit typing required
#TaskNode: #Task | #TaskGroup | #TaskSequence

// =============================================================================
// Task Output References
// =============================================================================
//
// Tasks produce stdout, stderr, and exitCode fields that evaluate to
// #TaskOutputRef structs. These can be referenced by other tasks:
//
//   tasks: {
//       tmpdir: { command: "mktemp", args: ["-d"] }
//       work: {
//           command: "ls"
//           env: TEMP_DIR: tasks.tmpdir.stdout
//       }
//   }
//
// Field names use no underscore prefix so they appear in JSON output.
// The Rust executor resolves these at runtime after upstream tasks complete.

#TaskOutputRef: {
	cuenvOutputRef: true
	cuenvTask:      string
	cuenvOutput:    "stdout" | "stderr" | "exitCode"
}

// =============================================================================
// Script Shell Configuration
// =============================================================================

// Interpreter for script-based tasks
#ScriptShell: "bash" | "sh" | "zsh" | "fish" | "nu" | "powershell" | "pwsh" | "python" | "node" | "ruby" | "perl"

// Shell options (for bash-like shells)
#ShellOptions: {
	errexit?:  bool | *true  // -e: exit on error
	nounset?:  bool | *true  // -u: error on undefined vars
	pipefail?: bool | *true  // -o pipefail: fail on pipe errors (bash/zsh only)
	xtrace?:   bool | *false // -x: debug/trace mode
}

// =============================================================================
// Task Cache Policy
// =============================================================================

#TaskCacheMode: "never" | "read" | "write" | "read-write"

#TaskCachePolicy: {
	// Cache mode (default: never)
	mode?: #TaskCacheMode | *"never"
	// Maximum age for cache reads, e.g. "30m", "1h", "infinite"
	maxAge?: string
}

// =============================================================================
// Hermeticity
// =============================================================================

// Object form of a task's `hermetic` field. Setting it always means
// hermeticity is on; there would be nothing to configure otherwise.
#HermeticPassthrough: string & !~"(?i)^HOME$"

#Hermetic: {
	// Host environment variable names the action is allowed to depend on.
	//
	// Their host values are folded into the cache key. HOME is deliberately
	// excluded: use hermetic: false when a host task must use the caller's home.
	// Hermetic tasks default to HOME=/home/builder, USER=builder, and
	// LOGNAME=builder. The host executor uses a Cuenv-managed writable HOME
	// if the fixed path is unavailable, and keys the action on the selected path.
	// Host values of names not listed here never enter the key: cuenv will not
	// silently key a result on the machine it was computed on. Omit the field
	// when a task's result does not depend on the host environment, which is
	// the portable case and the one a shared cache can serve.
	passthrough?: [...#HermeticPassthrough]

	// Filesystem isolation tier. Defaults to "dir".
	//
	//   "dir"  — the task runs in a per-action directory populated from its
	//            declared `inputs`, and only declared `outputs` are projected
	//            back. This isolates relative workspace reads and writes, but
	//            is not an OS security boundary: absolute host paths remain
	//            reachable. A symlinked input is followed and staged as a
	//            regular file; output symlinks are rejected.
	//   "none" — the task runs in the project directory and can read and
	//            write anything on the machine. Incomplete `inputs` produce
	//            stale cache hits, so entries recorded here are only ever as
	//            trustworthy as the declaration.
	//
	// Directory isolation is the default. Reach for "none" when a task must
	// touch the live checkout.
	sandbox?: #Sandbox
}

// Workspace filesystem isolation tiers. Strict OS-level confinement is not
// listed until it is implemented.
#Sandbox: "dir" | "none"

// Working directory base for object-shaped task dir values.
#TaskDirBase: "definition" | "caller" | "module"

// Working directory override. Resolves relative to the executable task
// definition, the importing/re-exporting caller, or the module.
#TaskDir: {
	from: #TaskDirBase | *"definition"
	path: string | *"."
}

// =============================================================================
// Single Executable Task
// =============================================================================

// Hidden helper fields used to derive fully-qualified task names from label aliases.
// Named tasks and group children get these from schema templates; sequence items
// still rely on the Go bridge because CUE does not yet support aliases on list
// elements.
#Task: {
	// GitHub token requirements for the job executing this task.
	ci?:          #TaskCI
	_cuenvPrefix: string | *""
	_cuenvSelf:   string | *""

	// Executable tasks use command/script; task groups use type: "group".
	type?: _|_

	// Fully-qualified task name used by runtime output references.
	// For named tasks and group children this is derived in schema via label aliases.
	// The Go bridge fills sequence item names (pipeline[0], etc.) before JSON serialization.
	// The default empty string preserves evaluation when no name has been injected yet.
	_name: string | *(_cuenvPrefix + _cuenvSelf)

	// Runtime output references - resolve to #TaskOutputRef structs.
	// Other tasks can reference these (e.g., tasks.tmpdir.stdout) to pass
	// runtime outputs between tasks. Resolved by Rust executor, not CUE.
	stdout: #TaskOutputRef & {cuenvTask: _name, cuenvOutput: "stdout"}
	stderr: #TaskOutputRef & {cuenvTask: _name, cuenvOutput: "stderr"}
	exitCode: #TaskOutputRef & {cuenvTask: _name, cuenvOutput: "exitCode"}

	// Command-based execution
	command?: string
	args?: [...(string | #TaskOutputRef)]

	// Script-based execution (mutually exclusive with command)
	script?:       string
	scriptShell?:  #ScriptShell | *"bash"
	shellOptions?: #ShellOptions

	// An executable task has exactly one execution mode.
	({command!: string, script?: _|_} | {script!: string, command?: _|_})

	// Environment variables
	// Host HOME is never passed through by a task env marker. A non-hermetic
	// host task inherits the caller's environment without declaring a marker.
	env?: {
		[string]: #EnvironmentVariable | #TaskOutputRef
		HOME?:    (string & !~"(?i)^cuenv:passthrough:HOME$") | int | bool | #Secret | #InterpolatedEnv | #EnvironmentVariableWithPolicies | #TaskOutputRef
	}

	// Working directory override. Defaults to the task definition directory.
	dir: #TaskDir

	// Hermeticity settings.
	//
	// When true (default), the task opts into hermetic execution: it is
	// eligible for the action cache, and its cache key records only what it
	// declares. When false, the task runs directly in the workspace with the
	// ambient host environment and is never cached, because the key would
	// describe a fraction of what produced the result.
	//
	// The object form additionally declares which host environment variables
	// the action may depend on. See #Hermetic.
	hermetic?: bool | #Hermetic | *true

	// Dependencies - reference other tasks or images for compile-time validation
	dependsOn?: [...(#TaskNode | #ContainerImage)]

	// Labels for task discovery via #TaskMatcher
	labels?: [...string]

	// Input files/patterns for caching and hermetic execution
	inputs?: [...#Input]

	// Output files/patterns for caching
	outputs?: [...string]

	// Per-task task-result cache policy
	cache?: #TaskCachePolicy

	// Human-readable description
	description?: string

	// Runtime override for this task
	runtime?: #Runtime

	// Task parameter definitions for CLI arguments
	params?: #TaskParams

	// Execution policies
	timeout?: string // e.g. "30m"
	retry?: {
		attempts: int | *3
		delay?:   string // e.g. "5s"
	}
	continueOnError?: bool | *false

	// Named regex captures extracted from task stdout/stderr after execution
	captures?: [string]: #TaskCapture

	// DEPRECATED: Use runtime: dagger: { ... } instead
	dagger?: #DaggerConfig
}

// =============================================================================
// Parallel Execution (Task Group)
// =============================================================================

#TaskGroup: {
	_cuenvPrefix: string | *""
	_cuenvSelf:   string | *""

	// Fully-qualified group path used to derive child task names.
	_name: string | *(_cuenvPrefix + _cuenvSelf)

	// Type discriminator - must be "group"
	type: "group"

	// Dependencies on other tasks
	dependsOn?: [...#TaskNode]

	// Limit concurrent executions (0 = unlimited)
	maxConcurrency?: int

	// Human-readable description
	description?: string

	// Named children - all run concurrently (as direct fields).
	// Task and group children derive their fully-qualified names from the
	// current group's _name. Sequence children keep their name context in the
	// bridge, which can see list indexes.
	// Select child validation from the group's existing type discriminator.
	// This avoids applying the recursive group pattern to every task-shaped
	// object while preserving the public task fields and flat child syntax.
	let _childrenByType = {
		group: {
			{[childName= !~"^(type|dependsOn|maxConcurrency|description)$"]: ((#Task | #TaskGroup) & {
				_cuenvPrefix: _name + "."
				_cuenvSelf:   childName
			}) | #TaskSequence
			}
		}
	}
	_childrenByType[type]
}

// =============================================================================
// Sequential Execution (Task Sequence)
// =============================================================================

// A sequence is simply an ordered list of task nodes - run in order
#TaskSequence: [...#TaskNode]

// =============================================================================
// Task Parameters
// =============================================================================

#TaskParams: {
	// Positional arguments (order matters, consumed left-to-right)
	positional?: [...#Param]
	// Named arguments are declared as direct fields (--flag style)
	[!~"^positional$"]: #Param
}

#Param: {
	description?: string
	required?:    bool | *false
	default?:     string
	type?:        "string" | "bool" | "int" | *"string"
	short?:       =~"^[a-zA-Z]$"
}

// =============================================================================
// Task Inputs
// =============================================================================

// Accepted task inputs:
// - string: File path, directory, or glob pattern
// - #ProjectReference: Cross-project task outputs
// - #TaskOutput: Same-project task outputs
#Input: string | #ProjectReference | *#TaskOutput

// Reference to another project's task within the same Git root
#ProjectReference: {
	project!: string
	task!:    string
	map!: [...#Mapping]
}

#Mapping: {
	from!: string
	to!:   string
}

// Reference to another task's outputs within the same project
#TaskOutput: {
	task!: string
	map?: [...#Mapping]
}

// =============================================================================
// Task Captures (Regex Extraction from Output)
// =============================================================================

// Regex capture from task output streams.
// The first capture group's match becomes the named value.
#TaskCapture: {
	pattern!: string
	source?:  "stdout" | "stderr" | *"stdout"
}

// Reference to a captured value, resolved at runtime by the executor.
// Usage in annotations:
//   annotations: "Preview URL": schema.#TaskCaptureRef & {
//       cuenvTask: "deploy.preview", cuenvCapture: "previewUrl"
//   }
#TaskCaptureRef: {
	cuenvCaptureRef: true
	cuenvTask!:      string
	cuenvCapture!:   string
}

// =============================================================================
// Dagger Configuration (Containerized Execution)
// =============================================================================

#DaggerConfig: {
	image?: string
	from?:  string
	secrets?: [...#DaggerSecret]
	cache?: [...#DaggerCacheMount]
}

#DaggerSecret: {
	name:     string
	path?:    string
	envVar?:  string
	resolver: #Secret
}

#DaggerCacheMount: {
	path: string
	name: string
}

package schema

// #ToolsRuntime provides multi-source tool management with platform overrides.
// Supports fetching tools from:
// - GitHub Releases (static binaries)
// - Nix flakes (complex toolchains)
// - OCI container images (custom distributions)
//
// Example:
//   runtime: #ToolsRuntime & {
//       platforms: ["darwin-arm64", "darwin-x86_64", "linux-x86_64"]
//       flakes: nixpkgs: "github:NixOS/nixpkgs/nixos-unstable"
//       tools: {
//           // GitHub releases with platform overrides
//           jq: {
//               version: "1.7.1"
//               overrides: [
//                   {os: "darwin", arch: "arm64", source: #GitHub & {repo: "jqlang/jq", asset: "jq-macos-arm64"}},
//                   {os: "darwin", arch: "x86_64", source: #GitHub & {repo: "jqlang/jq", asset: "jq-macos-amd64"}},
//                   {os: "linux", arch: "x86_64", source: #GitHub & {repo: "jqlang/jq", asset: "jq-linux-amd64"}},
//               ]
//           }
//
//           // Nix package
//           rust: {version: "1.83.0", source: #Nix & {flake: "nixpkgs", package: "rustc"}}
//       }
//   }
#ToolsRuntime: {
	type: "tools"
	// Platforms to resolve and lock
	platforms!: [...#Platform]
	// Named Nix flake references for pinning
	flakes?: [string]: string
	// GitHub provider configuration
	github?: #GitHubProvider
	// Tool specifications (version string or full #Tool)
	tools!: [string]: string | #Tool
	// Cache directory (defaults to ~/.cache/cuenv/tools)
	cacheDir?: string
}

// GitHub provider configuration
#GitHubProvider: {
	// Authentication token (must use secret resolver)
	token?: #Secret
}

// Supported platforms
#Platform: "darwin-arm64" | "darwin-x86_64" | "linux-x86_64" | "linux-arm64"

// OS for platform matching
#OS: "darwin" | "linux"

// Architecture for platform matching
#Arch: "arm64" | "x86_64"

// #Tool is a full tool specification with source and overrides
#Tool: {
	// Version string (e.g., "1.7.1", "latest")
	version!: string
	// Rename the binary in PATH
	as?: string
	// Default source for all platforms
	source?: #Source
	// Platform-specific source overrides
	overrides?: [...#Override]
}

// #Override specifies a source for specific platforms
#Override: {
	// Match by OS (darwin, linux)
	os?: #OS
	// Match by architecture (arm64, x86_64)
	arch?: #Arch
	// Source for matching platforms
	source!: #Source
}

// #Source is a union of all supported tool sources
#Source: #Oci | #GitHub | #Nix | #Rustup | #URL

// #Oci extracts binaries from OCI container images
#Oci: {
	type: "oci"
	// Image reference with optional {version}, {os}, {arch} templates
	image!: string
	// Path to binary inside the container
	path!: string
}

// #GitHub downloads from GitHub Releases
#GitHub: {
	type: "github"
	// Repository (owner/repo)
	repo!: string
	// Tag prefix (prepended to version, defaults to "")
	tagPrefix: string | *""
	// Release tag override (if set, ignores tagPrefix and uses this template directly)
	tag?: string
	// Asset name with optional {version}, {os}, {arch} templates
	asset!: string
	// Legacy path selector for single-file archive extraction.
	// Prefer `extract` for typed outputs.
	path?: string
	// Optional typed extraction rules for archive/pkg assets.
	// When omitted, cuenv treats the tool as a single binary.
	extract?: [...#GitHubExtract]
}

// Typed extraction items for GitHub assets.
#GitHubExtract: #BinExtract | #LibExtract | #IncludeExtract | #PkgConfigExtract | #FileExtract

#BinExtract: {
	kind:  "bin"
	path!: string
	as?:   string
}

#LibExtract: {
	kind:  "lib"
	path!: string
	// Optional env var to export this exact file path (for example FDB_CLIENT_LIB)
	env?: string
}

#IncludeExtract: {
	kind:  "include"
	path!: string
}

#PkgConfigExtract: {
	kind:  "pkgconfig"
	path!: string
}

#FileExtract: {
	kind:  "file"
	path!: string
	// Optional env var to export this exact file path.
	env?: string
}

// #Nix builds from a Nix flake
#Nix: {
	type: "nix"
	// Named flake reference (key in runtime.flakes)
	flake!: string
	// Package attribute (e.g., "jq", "python3")
	package!: string
	// Output path if binary can't be auto-detected
	output?: string
}

// #Rustup manages Rust toolchains via rustup
#Rustup: {
	type: "rustup"
	// Toolchain identifier (e.g., "stable", "1.83.0", "nightly-2024-01-01")
	toolchain!: string
	// Installation profile: minimal, default, complete
	profile: "minimal" | "default" | "complete" | *"default"
	// Additional components to install (e.g., "clippy", "rustfmt", "rust-src")
	components: [...string] | *[]
	// Additional targets to install (e.g., "x86_64-unknown-linux-gnu")
	targets: [...string] | *[]
}

// #URL downloads a tool from an arbitrary HTTP/HTTPS URL.
//
// Supports template variables in the URL:
//   - {version} - the tool version string
//   - {os}      - the target OS (darwin, linux)
//   - {arch}    - the target architecture (aarch64, x86_64)
//
// Example:
//   source: #URL & {
//       url: "https://example.com/releases/{version}/tool-{os}-{arch}.tar.gz"
//       path: "tool-{version}/bin/tool"
//   }
#URL: {
	type: "url"
	// Download URL with optional {version}, {os}, {arch} templates
	url!: string
	// Legacy path selector for single-file archive extraction.
	// Prefer `extract` for typed outputs.
	path?: string
	// Optional typed extraction rules for archive assets.
	// When omitted, cuenv treats the download as a single binary.
	extract?: [...#GitHubExtract]
}

// #ToolsActivate is a pre-configured hook that downloads tools
// and emits inferred exports based on tool output types (bin/lib/include/pkgconfig/file env).
//
// The hook runs `cuenv tools activate` which:
// 1. Reads `cuenv.lock` to find tools for the current platform
// 2. Downloads and extracts binaries (if not already cached)
// 3. Outputs inferred `export ...` statements
//
// Usage:
//   hooks: onEnter: tools: #ToolsActivate
#ToolsActivate: #ExecHook & {
	order:     10
	propagate: false
	command:   "cuenv"
	args: ["tools", "activate"]
	source: true
	inputs: ["cuenv.lock"]
}

package schema

// HashiCorp Vault secret
#VaultSecret: #Secret & {
	resolver: "vault"
	path:     string             // Path to secret (e.g., "myapp/config")
	key:      string             // Key within the secret
	mount:    string | *"secret" // Secret engine mount point
}

package schema

// #VcsDependency declares a cuenv-managed Git dependency.
//
// `vendor` and `path` are required so projects make an explicit choice between
// tracked source snapshots and local generated checkouts.
#VcsDependency: {
	// Git repository URL. Local paths are accepted by Git for tests and private mirrors.
	url!: string
	// Branch, tag, or commit-ish to resolve. Defaults to the remote default branch.
	reference: string | *"HEAD"
	// true copies a tracked snapshot; false writes generated content ignored by git.
	// Full-repo non-vendored dependencies keep .git metadata as local checkouts.
	vendor!: bool
	// Repository-relative materialization path.
	path!: string
	// Optional repo-relative subdirectory to materialize via sparse checkout.
	// When set, only this subtree is materialized at `path`.
	// Must be a forward-slash relative path with no ".", "..", or glob characters.
	subdir?: string
	// Overlay mode: materialize each immediate child of the subtree into its own
	// `path/<child>` and gitignore each child individually, instead of taking over
	// (and gitignoring) the whole `path`. This lets repo-local content live in
	// `path` alongside the synced children. Requires `subdir` and `vendor: false`.
	overlay?: bool
}

package codegen

// ============================================================================
// Project File Schemas - Language-specific file definitions
// ============================================================================

// #ProjectFile is the base schema for all generated file content
#ProjectFile: {
	// The actual code content
	content: string

	// Language identifier (for syntax highlighting and formatting)
	language: string

	// File generation mode
	// - managed: Always regenerated when cube is synced
	// - scaffold: Only created if file doesn't exist
	mode: "managed" | "scaffold" | *"managed"

	// Whether to add this file path to .gitignore
	// Defaults based on mode:
	//   - managed: defaults to true (generated files should be ignored)
	//   - scaffold: defaults to false (user-owned files should be committed)
	gitignore: bool
	if mode == "managed" {
		gitignore: *true | bool
	}
	if mode == "scaffold" {
		gitignore: *false | bool
	}

	// Formatting configuration
	format?: {
		indent:         "space" | "tab"
		indentSize?:    int & >=1 & <=8
		lineWidth?:     int & >=60 & <=200
		trailingComma?: "none" | "all" | "es5"
		semicolons?:    bool
		quotes?:        "single" | "double"
	}

	// Optional: validation/linting. When enabled, generated content is
	// validated during `cuenv sync codegen` (JSON syntax today; other
	// languages are accepted as a no-op until validators are added).
	lint?: {
		enabled: bool
	}
}

