// #Cachix sets up Cachix for Nix binary caching.
//
// Active when:
// - ci.provider.github.cachix is configured
//
// Injects tasks:
// - cuenv:contributor:cachix.setup: Sets up Cachix for binary caching
//
// This is a GitHub-specific contributor and uses cachix/cachix-action.
//
// Usage:
//
//	import "github.com/cuenv/cuenv/contrib/contributors"
//
//	ci: contributors: [contributors.#Cachix]
//	ci: provider: github: cachix: name: "my-cache"
#Cachix: schema.#Contributor & {
	id: "cachix"
	when: providerConfig: ["github.cachix"]
	tasks: [{
		id:        "cachix.setup"
		label:     "Setup Cachix"
		priority:  9
		dependsOn: ["nix.install"]
		provider: github: {
			uses: "cachix/cachix-action@v17"
			with: {
				name:      "${CACHIX_CACHE_NAME}"
				authToken: "${CACHIX_AUTH_TOKEN}"
			}
		}
	}]
}

package contributors

import "github.com/cuenv/cuenv/schema"

// #Cuenv installs or builds cuenv in CI environments.
//
// Always active - cuenv is needed to run tasks.
// The installation method depends on config.ci.cuenv.source:
// - release (default): Download pre-built binary from GitHub Releases
// - git: Build from git checkout (requires Nix)
// - nix: Install via Nix flake
// - homebrew: Install via Homebrew tap (no Nix required)
//
// Injects tasks:
// - cuenv:contributor:cuenv.setup: Sets up cuenv for the CI environment
//
// Usage:
//
//	import "github.com/cuenv/cuenv/contrib/contributors"
//
//	ci: contributors: [contributors.#Cuenv]
#Cuenv: schema.#Contributor & {
	id: "cuenv"
	when: always: true
	tasks: [{
		id:       "cuenv.setup"
		label:    "Setup cuenv"
		priority: 10
		env: GITHUB_TOKEN: "${{ secrets.GITHUB_TOKEN }}"
		script: """
			arch="$(uname -m)"
			case "$arch" in
			  x86_64|amd64) cuenv_asset="cuenv-linux-x64" ;;
			  aarch64|arm64) cuenv_asset="cuenv-linux-arm64" ;;
			  *) echo "Unsupported Linux architecture: $arch" >&2; exit 1 ;;
			esac
			cuenv_version="${CUENV_VERSION}"
			if [ -z "$cuenv_version" ]; then
			  cuenv_version="latest"
			fi
			if [ "$cuenv_version" = "latest" ]; then
			  cuenv_url="https://github.com/cuenv/cuenv/releases/latest/download/${cuenv_asset}"
			else
			  cuenv_url="https://github.com/cuenv/cuenv/releases/download/${cuenv_version}/${cuenv_asset}"
			fi
			curl -fsSL -o /usr/local/bin/cuenv "$cuenv_url" && chmod +x /usr/local/bin/cuenv && /usr/local/bin/cuenv sync ci
			"""
	}]
}

// #CuenvRelease installs cuenv from GitHub Releases (default mode)
// No Nix dependency required.
#CuenvRelease: schema.#Contributor & {
	id: "cuenv"
	when: cuenvSource: ["release"]
	tasks: [{
		id:       "cuenv.setup"
		label:    "Setup cuenv (release)"
		priority: 10
		env: GITHUB_TOKEN: "${{ secrets.GITHUB_TOKEN }}"
		script: """
			arch="$(uname -m)"
			case "$arch" in
			  x86_64|amd64) cuenv_asset="cuenv-linux-x64" ;;
			  aarch64|arm64) cuenv_asset="cuenv-linux-arm64" ;;
			  *) echo "Unsupported Linux architecture: $arch" >&2; exit 1 ;;
			esac
			cuenv_version="${CUENV_VERSION}"
			if [ -z "$cuenv_version" ]; then
			  cuenv_version="latest"
			fi
			if [ "$cuenv_version" = "latest" ]; then
			  cuenv_url="https://github.com/cuenv/cuenv/releases/latest/download/${cuenv_asset}"
			else
			  cuenv_url="https://github.com/cuenv/cuenv/releases/download/${cuenv_version}/${cuenv_asset}"
			fi
			curl -fsSL -o /usr/local/bin/cuenv "$cuenv_url" && chmod +x /usr/local/bin/cuenv && /usr/local/bin/cuenv sync -A
			"""
	}]
}

// #CuenvGit builds cuenv from git checkout using Nix.
// Requires Nix to be available from the runner or an earlier contributor.
#CuenvGit: schema.#Contributor & {
	id: "cuenv"
	when: cuenvSource: ["git"]
	tasks: [{
		id:       "cuenv.setup"
		label:    "Build cuenv"
		priority: 10
		env: GITHUB_TOKEN: "${{ secrets.GITHUB_TOKEN }}"
		script: """
			. /nix/var/nix/profiles/default/etc/profile.d/nix-daemon.sh
			nix develop -c cargo build --release -p cuenv
			echo "$(pwd)/target/release" >> "$GITHUB_PATH" 2>/dev/null || echo "$(pwd)/target/release" >> "$BUILDKITE_ENV_FILE" 2>/dev/null || true
			./target/release/cuenv sync ci
			"""
	}]
}

// #CuenvNative builds cuenv using native Rust/Go toolchains (no Nix)
// build.rs automatically compiles the Go CUE bridge via `go build`
#CuenvNative: schema.#Contributor & {
	id: "cuenv"
	when: cuenvSource: ["native"]
	tasks: [
		{
			id:       "cuenv.setup.rust"
			label:    "Setup Rust"
			priority: 6
			provider: github: uses: "dtolnay/rust-toolchain@stable"
		},
		{
			id:       "cuenv.setup.go"
			label:    "Setup Go"
			priority: 6
			provider: github: {
				uses: "actions/setup-go@v5"
				with: {
					"go-version":            "1.24"
					"cache-dependency-path": "crates/cuengine/go.sum"
				}
			}
		},
		{
			id:        "cuenv.setup"
			label:     "Build cuenv"
			priority:  10
			dependsOn: ["cuenv.setup.rust", "cuenv.setup.go"]
			env: GITHUB_TOKEN: "${{ secrets.GITHUB_TOKEN }}"
			script: """
				cargo build --release -p cuenv
				echo "$(pwd)/target/release" >> "$GITHUB_PATH" 2>/dev/null || echo "$(pwd)/target/release" >> "$BUILDKITE_ENV_FILE" 2>/dev/null || true
				./target/release/cuenv sync ci
				"""
		},
	]
}

// #CuenvFromArtifact sets up cuenv from a previously built artifact
// Used by CI jobs that depend on the build.cuenv job
#CuenvFromArtifact: schema.#Contributor & {
	id: "cuenv"
	when: cuenvSource: ["artifact"]
	tasks: [{
		id:       "cuenv.setup"
		label:    "Setup cuenv (from artifact)"
		priority: 10
		script: """
			chmod +x target/release/cuenv
			echo "$(pwd)/target/release" >> "$GITHUB_PATH" 2>/dev/null || echo "$(pwd)/target/release" >> "$BUILDKITE_ENV_FILE" 2>/dev/null || true
			./target/release/cuenv sync ci
			"""
	}]
}

// #CuenvNix builds cuenv from the checked-out repository flake.
// Requires Nix to be available from the runner or an earlier contributor.
#CuenvNix: schema.#Contributor & {
	id: "cuenv"
	when: cuenvSource: ["nix"]
	tasks: [{
		id:       "cuenv.setup"
		label:    "Build cuenv (nix)"
		priority: 10
		env: GITHUB_TOKEN: "${{ secrets.GITHUB_TOKEN }}"
		script: """
			. /nix/var/nix/profiles/default/etc/profile.d/nix-daemon.sh
			nix build .#cuenv -L --accept-flake-config
			echo "$(pwd)/result/bin" >> "$GITHUB_PATH" 2>/dev/null || echo "$(pwd)/result/bin" >> "$BUILDKITE_ENV_FILE" 2>/dev/null || true
			./result/bin/cuenv sync ci
			"""
	}]
}

// #CuenvHomebrew installs cuenv via Homebrew tap
// No Nix dependency required.
#CuenvHomebrew: schema.#Contributor & {
	id: "cuenv"
	when: cuenvSource: ["homebrew"]
	tasks: [{
		id:       "cuenv.setup"
		label:    "Setup cuenv (homebrew)"
		priority: 10
		env: GITHUB_TOKEN: "${{ secrets.GITHUB_TOKEN }}"
		command: "brew"
		args: ["install", "cuenv/cuenv/cuenv"]
	}, {
		id:        "cuenv.sync"
		label:     "Sync cuenv tools"
		priority:  11
		dependsOn: ["cuenv.setup"]
		command:   "cuenv"
		args: ["sync", "-A"]
	}]
}

